import { useEffect, useReducer, useState, useRef, useContext } from "react";
import axios from "../app/api/axios";
import initialState from "../store";
import reducer from "../reducer";
import { Link } from "react-router-dom";
import AuthContext from "../context/authProvider";
import {
  faCheck,
  faTimes,
  faInfoCircle,
  faEye,
  faEyeSlash,
} from "@fortawesome/free-solid-svg-icons";

import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";

const Register = () => {
  const [state, dispatch] = useReducer(reducer, initialState);
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [pwd, setPwd] = useState("");
  const [confirmPwd, setConfirmPwd] = useState("");
  const userRef = useRef();
  const errRef = useRef();
  const [isPassword, setisPassword] = useState("password");
  const [isPassword2, setisPassword2] = useState("password");
  const [passwordCheck, setPasswordCheck] = useState(faEyeSlash);
  const { auth } = useContext(AuthContext);
  const [verified, setVerified] = useState(false);
  const [validName, setValidName] = useState(false);
  const [validPwd, setValidPwd] = useState(false);
  const [userFocus, setUserFocus] = useState(false);
  const [pwdFocus, setPwdFocus] = useState(false);
  const now = new Date();

  const USER_REGEX = /^[A-z][A-z0-9-_]{2,23}$/;
  // const EMAIL_REGEX = /^(?=.*[a-z])(?=.*[!@#$%]).{3,50}$/;
  const PWD_REGEX = /^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[!@#$%]).{8,24}$/;

  const getUsers = async () => {
    const response = await axios.get("/register");
    console.log(response.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newUser = {
      username: username,
      email: email,
      password: pwd,
      date: now,
    };
    console.log(newUser);
    const response = await axios.post("/register", newUser);
  };

  // useEffect(() => {
  //   getUsers();
  // }, []);

  return (
    <div className="register">
      <h3>Register</h3>
      <form className="register-form" onSubmit={handleSubmit}>
        <label htmlFor="username">name</label>
        <FontAwesomeIcon
          icon={faCheck}
          className={validName ? "valid" : "hide"}
        />
        <FontAwesomeIcon
          icon={faTimes}
          className={validName || !username ? "hide" : "invalid"}
        />
        <input
          value={username}
          type="text"
          ref={userRef}
          autoComplete="off"
          onChange={(e) => setUsername(e.target.value)}
          required
          aria-invalid={validName ? "false" : "true"}
          aria-describedby="uidnote"
          onFocus={() => setUserFocus(true)}
          onBlur={() => setUserFocus(false)}
        />
        <p>
          <FontAwesomeIcon icon={faInfoCircle} />
          3 to 24 characters
          <br />
          must begin with a letter
          <br />
          numbers, underscores, hyphens are allowed
        </p>
        <label htmlFor="email">email</label>

        <input
          value={email}
          type="text"
          autoComplete="off"
          onChange={(e) => setEmail(e.target.value)}
          required
          aria-describedby="uidnote"
        />
        <label htmlFor="password">
          password
          <FontAwesomeIcon
            icon={faCheck}
            className={validPwd ? "valid" : "hide"}
          />
          <FontAwesomeIcon
            icon={faTimes}
            className={validPwd || !pwd ? "hide" : "invalid"}
          />
        </label>
        <input
          value={pwd}
          type={isPassword}
          className="password"
          onChange={(e) => setPwd(e.target.value)}
          required
          aria-invalid={validPwd ? false : true}
          aria-describedby="pwdnote"
          onFocus={() => setPwdFocus(true)}
          onBlur={() => setPwdFocus(false)}
        />
        <p>
          <FontAwesomeIcon icon={faInfoCircle} />
        </p>
        <label>confrirm password</label>

        <input
          value={confirmPwd}
          type="text"
          onChange={(e) => setConfirmPwd(e.target.value)}
        />
        <br />
        <button type="submit">sign up</button>
      </form>
      <article className="sign-up-cont">
        <p>Already registered? </p>

        {/*put router link here*/}
        <Link
          style={{
            color: "blue",
          }}
          to={"/login"}
        >
          Sign In
        </Link>
      </article>
    </div>
  );
};

export default Register;
